python3 -c "
import csv
with open('residual/residues.csv') as f:
    r = csv.reader(f)
    header = next(r)
    cols = header[1:]
    totals = {c:0 for c in cols}
    rows = list(r)
    for row in rows:
        for c, v in zip(cols, row[1:]):
            if v.strip() == '1':
                totals[c]+=1
    for c in cols:
        print(f'{c}: {totals[c]}')
"
